    private static func make(_ id: String, _ name: String, _ arabic: String, _ french: String, _ english: String, _ description: String, _ regions: [Region], _ categories: [RecipeCategory], _ prep: Int, _ cook: Int, _ difficulty: Difficulty, _ servings: Int, _ ingredients: [(String, Double, String, String?)], _ instructions: [String], _ tips: [String], _ note: String, _ tags: [String]) -> Recipe {
        Recipe(
            id: id,
            name: name,
            arabicName: arabic,
            frenchName: french,
            englishName: english,
            imageName: id,
            shortDescription: description,
            regions: regions,
            categories: categories,
            preparationMinutes: prep,
            cookingMinutes: cook,
            difficulty: difficulty,
            servings: servings,
            ingredients: ingredients.enumerated().map { index, item in
                Ingredient(id: "\(id)-ingredient-\(index)", name: item.0, quantity: item.1, unit: item.2, note: item.3)
            },
            instructions: instructions,
            cookingTips: tips,
            traditionalNote: note,
            tags: tags
        )
    }
}
